import os
import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

convt3d_decl = r"""
#include <torch/extension.h>
torch::Tensor convt3d48_k3_forward(torch::Tensor x,
                               torch::Tensor w,
                               c10::optional<torch::Tensor> b);
"""

convt3d_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cute/tensor.hpp>
using namespace cute;
// ConvTranspose3d (stride=1, pad=0, output_padding=0, groups=1, kernel 3x3x3, C_in=48, C_out=48).
// Each CTA owns a 4x4x8 output tile (widened along the contiguous W dim), stages the 6x6x10
// (halo=2) input tile for 16 input channels per slab in shared memory, then loops over the 48
// input channels accumulating into all 48 output channels. 192 threads = 16 spatial groups
// (4 lh x 4 lw positions, each covering ld=0..3 and 2 W outputs) x 12 groups of 4 oc. Weights
// are staged tap-major so each thread's 4 output-channel weights are contiguous: the inner
// loop issues one float4 shared load per tap plus float2 activation loads, cutting shared
// memory load instructions ~2.4x and leaving the kernel FMA-throughput bound.
__device__ __forceinline__ void cp_async4_zfill(void* smem_dst, const void* gmem_src, bool pred) {
  const uint32_t saddr = static_cast<uint32_t>(__cvta_generic_to_shared(smem_dst));
  const int src_sz = pred ? 4 : 0;
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
               :: "r"(saddr), "l"(gmem_src), "r"(src_sz));
}
__device__ __forceinline__ void cp_async_commit_group() {
  asm volatile("cp.async.commit_group;\n" ::);
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
  asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}
__global__ void __launch_bounds__(192) convt3d48_k3_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    const int Din, const int Hin, const int Win,
    const int Dout, const int Hout, const int Wout)
{
  constexpr int CIN  = 48;
  constexpr int COUT = 48;
  constexpr int TILE   = 4;
  constexpr int TILEW  = 8;
  constexpr int HALO   = 2;
  constexpr int SXW    = TILEW + HALO;
  constexpr int SX_VOL = 6 * 6 * SXW;
  constexpr int IC_SLAB = 16;
  constexpr int NUM_SLABS = CIN / IC_SLAB;
  static_assert(CIN % IC_SLAB == 0, "IC_SLAB must divide CIN");
  extern __shared__ float smem_pool[];
  float* sX_raw = smem_pool;
  float* sW_raw = smem_pool + 2 * IC_SLAB * SX_VOL;
  // Input-channel slab tiling, now double buffered: two 16-channel 6x6x10
  // halo tiles (2 x 23,040 B) plus double-buffered tap-major weights total
  // ~56 KB of dynamic shared memory (opt-in via cudaFuncSetAttribute),
  // preserving halo reuse, the width-fastest sX layout, and the 4x2x4
  // register block with vectorized float4/float2 shared-memory loads.
  // sX is addressed via raw pointers (stage_slab / compute loop below): two
  // buffers of stride IC_SLAB*SX_VOL, inner strides (SX_VOL, 6*SXW, SXW, 1).
  // +4 padding on the tap-major weight leading dim breaks severe shared-memory
  // bank conflicts during weight staging: with leading dim 48 (== 16 mod 32)
  // all 27 taps stored by a warp land on just 2 banks (16-way conflicts);
  // stride 52 (== 20 mod 32) spreads consecutive taps over 8 distinct banks
  // (max ~4-way). Each thread's 4 output channels stay contiguous and 16B
  // aligned, so the float4 compute-side loads are unaffected.
  constexpr int SW_LD = COUT + 4;
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_layout(
          make_shape(Int<2>{}, Int<27>{}, Int<COUT>{}),
          make_stride(Int<27 * SW_LD>{}, Int<SW_LD>{}, Int<1>{})));
  const int n   = blockIdx.y;
  const int tid = threadIdx.x;
  const int tw = (Wout + TILEW - 1) / TILEW;
  const int th = (Hout + TILE - 1) / TILE;
  int t = blockIdx.x;
  const int tx = t % tw;  t /= tw;
  const int ty = t % th;
  const int tz = t / th;
  const int od0 = tz * TILE;
  const int oh0 = ty * TILE;
  const int ow0 = tx * TILEW;
  Tensor gX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * CIN * Din * Hin * Win),
      make_shape(Int<CIN>{}, Din, Hin, Win),
      make_stride(Din * Hin * Win, Hin * Win, Win, Int<1>{}));
  Tensor gY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * COUT * Dout * Hout * Wout),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(Dout * Hout * Wout, Hout * Wout, Wout, Int<1>{}));
  Tensor gW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CIN>{}, Int<COUT>{}, Int<3>{}, Int<3>{}, Int<3>{}),
      make_stride(Int<COUT * 27>{}, Int<27>{}, Int<9>{}, Int<3>{}, Int<1>{}));
  const int spg = tid & 15;   // 16 spatial groups; each thread covers ld=0..3 and 2 W positions
  const int grp = tid >> 4;   // 12 groups of 4 output channels
  const int ocb = grp * 4;
  const int lh = (spg >> 2) & 3;
  const int lw = spg & 3;
  const int oh = oh0 + lh;
  const int ow = ow0 + lw * 2;
  const bool hvalid = (oh < Hout);
  float acc[4][2][4];
#pragma unroll
  for (int i = 0; i < 4; ++i) {
    const float bv = (B != nullptr) ? B[ocb + i] : 0.0f;
#pragma unroll
    for (int p = 0; p < 4; ++p) {
#pragma unroll
      for (int ws = 0; ws < 2; ++ws) {
        acc[p][ws][i] = bv;
      }
    }
  }
  // Pipelined input staging: halo tiles are loaded with cp.async (4B per
  // element, zero-fill for out-of-bounds taps) into a double-buffered sX.
  // While the CTA computes on slab s, the copy engine fetches slab s+1,
  // hiding the global-memory latency of staging behind the FMA-heavy icl loop.
  auto stage_slab = [&](int slab_idx, int buf) {
    const int icb = slab_idx * IC_SLAB;
    float* sXb = sX_raw + buf * (IC_SLAB * SX_VOL);
    for (int idx = tid; idx < IC_SLAB * SX_VOL; idx += blockDim.x) {
      const int icl = idx / SX_VOL;
      const int q   = idx - icl * SX_VOL;
      const int a   = q / (6 * SXW);
      const int r   = q - a * (6 * SXW);
      const int b   = r / SXW;
      const int c   = r - b * SXW;
      const int gd = od0 - HALO + a;
      const int gh = oh0 - HALO + b;
      const int gw = ow0 - HALO + c;
      const bool in = (gd >= 0 && gd < Din && gh >= 0 && gh < Hin && gw >= 0 && gw < Win);
      const float* src = in ? &gX(icb + icl, gd, gh, gw) : X;
      cp_async4_zfill(sXb + idx, src, in);
    }
  };
  stage_slab(0, 0);
  cp_async_commit_group();
  for (int slab = 0; slab < NUM_SLABS; ++slab) {
    const int ic_base = slab * IC_SLAB;
    const int buf = slab & 1;
    // Prefetch the next slab's halo tile into the other sX buffer; it is
    // consumed only after this slab's compute finishes.
    if (slab + 1 < NUM_SLABS) {
      stage_slab(slab + 1, buf ^ 1);
    }
    cp_async_commit_group();
    // Groups complete in commit order, so with the next slab's group still
    // in flight, waiting for at most one pending group guarantees this
    // slab's tile is fully resident in shared memory.
    if (slab + 1 < NUM_SLABS) {
      cp_async_wait_group<1>();
    } else {
      cp_async_wait_group<0>();
    }
    __syncthreads();
    // Preload the first weight slice of this slab into buffer 0.
    for (int idx = tid; idx < COUT * 27; idx += blockDim.x) {
      const int oc  = idx / 27;
      const int tap = idx - oc * 27;
      const int kd  = tap / 9;
      const int kh  = (tap / 3) % 3;
      const int kw  = tap % 3;
      sW(0, tap, oc) = gW(ic_base, oc, kd, kh, kw);
    }
    __syncthreads();
    for (int icl = 0; icl < IC_SLAB; ++icl) {
      const int cur = icl & 1;
      const int nxt = cur ^ 1;
      // Overlap the next in-slab weight-slice load with the current compute phase.
      if (icl + 1 < IC_SLAB) {
        for (int idx = tid; idx < COUT * 27; idx += blockDim.x) {
          const int oc  = idx / 27;
          const int tap = idx - oc * 27;
          const int kd  = tap / 9;
          const int kh  = (tap / 3) % 3;
          const int kw  = tap % 3;
          sW(nxt, tap, oc) = gW(ic_base + icl + 1, oc, kd, kh, kw);
        }
      }
#pragma unroll
      for (int kh = 0; kh < 3; ++kh) {
        const int sh = lh + HALO - kh;
        // Stage a 6 (depth) x 4 (width) activation window in registers with
        // vectorized float2 shared-memory loads (sX rows are width-fastest and
        // every element read here is 8B aligned), halving activation loads.
        float a[6][4];
        const float* sXr = sX_raw + buf * (IC_SLAB * SX_VOL) + icl * SX_VOL + sh * SXW + lw * 2;
#pragma unroll
        for (int d = 0; d < 6; ++d) {
          const float2 v0 = *reinterpret_cast<const float2*>(sXr + d * (6 * SXW));
          const float2 v1 = *reinterpret_cast<const float2*>(sXr + d * (6 * SXW) + 2);
          a[d][0] = v0.x; a[d][1] = v0.y;
          a[d][2] = v1.x; a[d][3] = v1.y;
        }
#pragma unroll
        for (int kw = 0; kw < 3; ++kw) {
#pragma unroll
          for (int kd = 0; kd < 3; ++kd) {
            const int tap = kd * 9 + kh * 3 + kw;
            // Tap-major sW keeps this thread's 4 output-channel weights
            // contiguous and 16B aligned: one float4 shared load per tap feeds
            // all 8 spatial outputs this thread owns.
            const float4 wv = *reinterpret_cast<const float4*>(
                sW_raw + cur * (27 * SW_LD) + tap * SW_LD + ocb);
#pragma unroll
            for (int p = 0; p < 4; ++p) {
#pragma unroll
              for (int ws = 0; ws < 2; ++ws) {
                const float av = a[p + HALO - kd][ws + HALO - kw];
                acc[p][ws][0] += av * wv.x;
                acc[p][ws][1] += av * wv.y;
                acc[p][ws][2] += av * wv.z;
                acc[p][ws][3] += av * wv.w;
              }
            }
          }
        }
      }
      // Make the prefetched buffer visible before the next in-slab iteration.
      __syncthreads();
    }
  }
#pragma unroll
  for (int p = 0; p < 4; ++p) {
    const int od = od0 + p;
#pragma unroll
    for (int ws = 0; ws < 2; ++ws) {
      const int oww = ow + ws;
      if (hvalid && od < Dout && oww < Wout) {
#pragma unroll
        for (int i = 0; i < 4; ++i) {
          gY(ocb + i, od, oh, oww) = acc[p][ws][i];
        }
      }
    }
  }
}
torch::Tensor convt3d48_k3_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x/w must be CUDA");
  TORCH_CHECK(x.dim() == 5 && w.dim() == 5, "x/w must be 5D");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat, "float32 only");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  const int64_t N   = x_c.size(0);
  const int64_t Din = x_c.size(2);
  const int64_t Hin = x_c.size(3);
  const int64_t Win = x_c.size(4);
  TORCH_CHECK(x_c.size(1) == 48, "Cin must be 48");
  TORCH_CHECK(w_c.size(0) == 48 && w_c.size(1) == 48, "weight must be [48,48,3,3,3]");
  TORCH_CHECK(w_c.size(2) == 3 && w_c.size(3) == 3 && w_c.size(4) == 3, "kernel must be 3x3x3");
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == 48, "bias must be [48]");
    b_ptr = b_c.data_ptr<float>();
  }
  const int64_t Dout = Din + 2;
  const int64_t Hout = Hin + 2;
  const int64_t Wout = Win + 2;
  auto y = torch::empty({N, 48, Dout, Hout, Wout}, x_c.options());
  const int64_t td = (Dout + 3) / 4;
  const int64_t th = (Hout + 3) / 4;
  const int64_t tw = (Wout + 7) / 8;
  dim3 block(192);
  dim3 grid((unsigned)(td * th * tw), (unsigned)N);
  auto stream = c10::cuda::getCurrentCUDAStream();
  constexpr int SMEM_BYTES = static_cast<int>((2 * 16 * 360 + 2 * 27 * (48 + 4)) * sizeof(float));
  TORCH_CHECK(cudaFuncSetAttribute(convt3d48_k3_kernel,
                                   cudaFuncAttributeMaxDynamicSharedMemorySize,
                                   SMEM_BYTES) == cudaSuccess,
              "failed to opt in to >48KB dynamic shared memory");
  convt3d48_k3_kernel<<<grid, block, SMEM_BYTES, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)Din, (int)Hin, (int)Win,
      (int)Dout, (int)Hout, (int)Wout);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""
def _find_cutlass_include():
    """Locate (or provision) a CUTLASS checkout that provides cute/tensor.hpp."""
    cands = []
    env = os.environ.get("CUTLASS_PATH") or os.environ.get("CUTLASS_DIR")
    if env:
        cands += [os.path.join(env, "include"), env]
    # CUTLASS headers bundled with an installed PyTorch (third_party/cutlass).
    try:
        tdir = os.path.dirname(torch.__file__)
        cands += [os.path.join(tdir, "include"),
                  os.path.join(tdir, "include", "cutlass", "include"),
                  os.path.join(tdir, "_inductor", "cutlass", "include")]
    except Exception:
        pass
    try:
        import cutlass
        p = os.path.dirname(cutlass.__file__)
        cands += [p, os.path.join(p, "include"),
                  os.path.join(os.path.dirname(p), "cutlass", "include")]
    except Exception:
        pass
    cands += ["/usr/local/cutlass/include", "/opt/cutlass/include",
              os.path.expanduser("~/cutlass/include")]
    for c in cands:
        if c and os.path.exists(os.path.join(c, "cute", "tensor.hpp")):
            return c
    # Last resort: provision a shallow CUTLASS clone into a writable cache dir.
    cache = os.environ.get("CUTLASS_CACHE") or os.path.join(
        os.path.expanduser("~"), ".cache", "cutlass")
    inc = os.path.join(cache, "include")
    if os.path.exists(os.path.join(inc, "cute", "tensor.hpp")):
        return inc
    try:
        import subprocess
        os.makedirs(os.path.dirname(cache), exist_ok=True)
        subprocess.check_call(
            ["git", "clone", "--depth", "1",
             "https://github.com/NVIDIA/cutlass.git", cache])
        if os.path.exists(os.path.join(inc, "cute", "tensor.hpp")):
            return inc
    except Exception:
        pass
    return None
_CUTLASS_INC = _find_cutlass_include()
if _CUTLASS_INC is None:
    raise RuntimeError(
        "CUTLASS/CuTe headers not found and could not be provisioned. Set "
        "CUTLASS_PATH to a cutlass checkout (needs <root>/include/cute/tensor.hpp), "
        "or ensure network access so a shallow clone can be fetched."
    )
_convt3d_mod = None
def _get_convt3d():
    global _convt3d_mod
    if _convt3d_mod is None:
        _convt3d_mod = load_inline(
            name="convt3d48_k3_cute",
            cpp_sources=convt3d_decl,
            cuda_sources=convt3d_src,
            functions=["convt3d48_k3_forward"],
            extra_include_paths=[_CUTLASS_INC],
            extra_cuda_cflags=["-O3", "-std=c++17", "--expt-relaxed-constexpr", "--expt-extended-lambda"],
            verbose=True,
        )
    return _convt3d_mod
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert in_channels == 48 and out_channels == 48 and kernel_size == 3
        assert stride == 1 and padding == 0 and output_padding == 0 and groups == 1
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size=(kernel_size, kernel_size, kernel_size), stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)
        self._mod = _get_convt3d()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._mod.convt3d48_k3_forward(x, self.conv_transpose3d.weight, self.conv_transpose3d.bias)

